// features/lifecycle.feature: A certificate that expires today can still be approved
import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review whose insurance certificate expires today (the API's "today" is the UTC date)
  const today = new Date().toISOString().slice(0, 10);
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const certificate = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate_today.txt",
          mimeType: "text/plain",
          buffer: Buffer.from(
            `Insurer: Harbor Mutual\nPolicy Number: HM-55-7707\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`,
          ),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(submitted.status).toBe("in_review");
  const pending = await factory.extraction(certificate.id, "reviewer");
  expect(pending.status, "insurance extraction awaits review").toBe("pending_review");
  const reviewer = await apiAs("reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${pending.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus<Extraction>(response, 200);
  expect(decided.status).toBe("approved");
  const stored = await factory.extraction(certificate.id, "reviewer");
  expect(stored.status).toBe("approved");
});
